/**
 * PATCH 855: Enhanced resilient fetch for slow mobile networks
 * - Timeout: 30s initial, up to 60s for retries
 * - 5 retries with exponential backoff
 * - Works on 3G, LTE, 5G with high latency
 */
const createResilientFetch = () => {
  const MAX_RETRIES = 5;
  const INITIAL_TIMEOUT = 30000; // 30 seconds - enough for slow connections
  const MAX_TIMEOUT = 60000; // 60 seconds max
  
  // Check connection quality
  const getConnectionQuality = (): 'slow' | 'medium' | 'fast' => {
    if ('connection' in navigator) {
      const conn = (navigator as any).connection;
      const effectiveType = conn?.effectiveType;
      if (effectiveType === 'slow-2g' || effectiveType === '2g' || conn?.saveData) {
        return 'slow';
      }
      if (effectiveType === '3g') {
        return 'medium';
      }
    }
    return 'fast';
  };

  return async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url;
    const isAuthRequest = url.includes('/auth/');
    let lastError: Error | null = null;
    
    const quality = getConnectionQuality();
    const timeoutMultiplier = quality === 'slow' ? 2 : quality === 'medium' ? 1.5 : 1;
    const retries = quality === 'slow' ? MAX_RETRIES : quality === 'medium' ? 4 : 3;
    
    for (let attempt = 0; attempt < retries; attempt++) {
      const controller = new AbortController();
      const baseTimeout = isAuthRequest ? INITIAL_TIMEOUT * 1.5 : INITIAL_TIMEOUT;
      const timeout = Math.min(baseTimeout * Math.pow(1.3, attempt) * timeoutMultiplier, MAX_TIMEOUT);
      const timeoutId = setTimeout(() => controller.abort(), timeout);
      
      try {
        console.log(`[Supabase] Request attempt ${attempt + 1}/${retries}, timeout: ${Math.round(timeout / 1000)}s`);
        
        const response = await fetch(input, {
          ...init,
          signal: controller.signal,
        });
        
        clearTimeout(timeoutId);
        
        // Success or client error (4xx) - return immediately
        if (response.ok || (response.status >= 400 && response.status < 500)) {
          return response;
        }
        
        // Server error (5xx) - retry with backoff
        if (response.status >= 500) {
          lastError = new Error(`Server error: ${response.status}`);
          console.warn(`[Supabase] Server error ${response.status}, retry ${attempt + 1}/${retries}`);
          const delay = 1000 * Math.pow(2, attempt);
          await new Promise(r => setTimeout(r, delay));
          continue;
        }
        
        return response;
      } catch (error: any) {
        clearTimeout(timeoutId);
        lastError = error;
        
        const isNetworkError = 
          error.name === 'AbortError' || 
          error.message?.includes('Failed to fetch') ||
          error.message?.includes('NetworkError') ||
          error.message?.includes('network');
        
        if (isNetworkError && attempt < retries - 1) {
          console.warn(`[Supabase] Network error, retry ${attempt + 1}/${retries}:`, error.message);
          const delay = 1000 * Math.pow(2, attempt);
          await new Promise(r => setTimeout(r, delay));
          continue;
        }
        
        // Non-retryable or final attempt
        if (attempt === retries - 1) {
          console.error(`[Supabase] All ${retries} retries exhausted for:`, url);
        }
        
        throw error;
      }
    }
    
    throw lastError || new Error('Failed after all retries');
  };
};

