// Export connection status helper
export const checkSupabaseConnection = async (): Promise<boolean> => {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);
    
    const { error } = await supabase.from('organizations').select('id').limit(1).maybeSingle();
    
    clearTimeout(timeoutId);
    return !error;
  } catch {
    return false;
  }
};

// Export connection quality check
export const getNetworkStatus = () => {
  const online = typeof navigator !== 'undefined' ? navigator.onLine : true;
  
  let quality: 'slow' | 'medium' | 'fast' | 'offline' = 'fast';
  let effectiveType = '4g';
  let rtt = 0;
  
  if (!online) {
    quality = 'offline';
  } else if ('connection' in navigator) {
    const conn = (navigator as any).connection;
    effectiveType = conn?.effectiveType || '4g';
    rtt = conn?.rtt || 0;
    
    if (effectiveType === 'slow-2g' || effectiveType === '2g' || conn?.saveData) {
      quality = 'slow';
    } else if (effectiveType === '3g' || rtt > 300) {
      quality = 'medium';
    }
  }
  
  return { online, quality, effectiveType, rtt };
};
